from pathlib import Path
import re

path = Path('/home/ubuntu/personal-ai-venture-os/client/src/pages/Home.tsx')
text = path.read_text()
new = r'''function DashboardCharts() { const { isAuthenticated } = useAuth(); const githubQuery = trpc.github.status.useQuery(undefined, { enabled: isAuthenticated, retry: false }); const [range, setRange] = useState("7d"); const github = githubQuery.data?.connected ? githubQuery.data : null; const progressData = github ? [{ name: github.repo.split("/").pop() ?? "GitHub", value: github.health }, ...projectProgressData.slice(0, 3)] : projectProgressData; const marketData = github ? marketSignalData.map((item, index) => index === marketSignalData.length - 1 ? { ...item, signals: Math.max(item.signals, github.recentCommits), opportunities: Math.max(item.opportunities, Math.min(github.openIssues, 9)) } : item) : marketSignalData; return <section className="charts-grid"><Card className="chart-card"><div className="panel-head"><div><p className="eyebrow">Project pulse</p><h2>تقدم المشاريع</h2><span className="chart-note">{github ? "تتضمن حالة مستودع GitHub المرتبط" : "نسبة الإنجاز الحالية لكل مشروع"}</span></div><select value={range} onChange={(e) => setRange(e.target.value)} aria-label="فترة الرسم"><option value="7d">هذا الأسبوع</option><option value="30d">هذا الشهر</option></select></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><BarChart data={progressData} layout="vertical" margin={{ top: 8, right: 12, left: 8, bottom: 8 }}><CartesianGrid strokeDasharray="3 3" horizontal={false} stroke="var(--border)" /><XAxis type="number" domain={[0, 100]} tick={{ fill: "var(--muted-foreground)", fontSize: 10 }} axisLine={false} tickLine={false} /><YAxis dataKey="name" type="category" width={84} tick={{ fill: "var(--foreground)", fontSize: 10 }} axisLine={false} tickLine={false} /><Tooltip cursor={{ fill: "var(--accent)" }} contentStyle={{ background: "var(--popover)", border: "1px solid var(--border)", borderRadius: 8, color: "var(--popover-foreground)", fontFamily: "Cairo" }} formatter={(value) => [`${value}%`, "الإنجاز"]} /><Bar dataKey="value" fill="var(--foreground)" radius={[0, 4, 4, 0]} barSize={14} /></BarChart></ResponsiveContainer></div></Card><Card className="chart-card"><div className="panel-head"><div><p className="eyebrow">Market signals</p><h2>إشارات السوق</h2><span className="chart-note">{github ? `محدثة من GitHub: ${github.openIssues} issues و${github.openPullRequests} PRs` : "الإشارات والفرص التي اكتشفها المسح اليومي"}</span></div><div className="chart-legend"><span><i className="legend-line solid" /> إشارات</span><span><i className="legend-line dashed" /> فرص</span></div></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><LineChart data={marketData} margin={{ top: 8, right: 8, left: -12, bottom: 4 }}><CartesianGrid strokeDasharray="3 3" stroke="var(--border)" /><XAxis dataKey="day" tick={{ fill: "var(--muted-foreground)", fontSize: 9 }} axisLine={false} tickLine={false} /><YAxis tick={{ fill: "var(--muted-foreground)", fontSize: 9 }} axisLine={false} tickLine={false} width={24} /><Tooltip contentStyle={{ background: "var(--popover)", border: "1px solid var(--border)", borderRadius: 8, color: "var(--popover-foreground)", fontFamily: "Cairo" }} /><Line type="monotone" dataKey="signals" stroke="var(--foreground)" strokeWidth={2} dot={{ r: 3, fill: "var(--foreground)" }} activeDot={{ r: 5 }} name="إشارات" /><Line type="monotone" dataKey="opportunities" stroke="var(--muted-foreground)" strokeWidth={2} strokeDasharray="5 5" dot={{ r: 3, fill: "var(--background)", stroke: "var(--foreground)" }} name="فرص" /></LineChart></ResponsiveContainer></div></Card></section>; }
'''
text, count = re.subn(r'function DashboardCharts\(\) \{.*?\nfunction Overview', new + '\nfunction Overview', text, count=1, flags=re.S)
if count != 1:
    raise SystemExit(f'DashboardCharts replacement count={count}')
path.write_text(text)
print('wired GitHub status into charts')
